"""User-facing ORBIT product dashboard."""
from __future__ import annotations

DASHBOARD_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ORBIT — AI Control Plane</title>
<style>
:root{color-scheme:dark;--bg:#070a10;--card:#101827;--line:#24324a;--text:#edf3fb;--muted:#91a0b7;--accent:#7c9cff;--ok:#43d19a;--warn:#f0b45b;--danger:#f06d7a}
*{box-sizing:border-box}body{margin:0;font:14px system-ui,-apple-system,Segoe UI,sans-serif;background:radial-gradient(circle at 10% 0,#18243b,#070a10 45%);color:var(--text)}button,input,textarea,select{font:inherit}button{border:0;border-radius:9px;padding:10px 14px;background:var(--accent);color:#07101d;font-weight:750;cursor:pointer}button.alt{background:#182338;color:var(--text);border:1px solid var(--line)}button.danger{background:#351923;color:#ffb3bd;border:1px solid #5d2934}.app{display:grid;grid-template-columns:230px 1fr;min-height:100vh}.side{padding:22px 14px;border-right:1px solid var(--line);background:#090e17e8;position:sticky;top:0;height:100vh}.brand{font-size:27px;font-weight:900;letter-spacing:.1em}.muted{color:var(--muted)}.nav{display:grid;gap:5px;margin-top:26px}.nav button{background:transparent;color:var(--muted);text-align:left}.nav button.active,.nav button:hover{background:#142036;color:var(--text)}.state{margin-top:22px;border:1px solid var(--line);border-radius:12px;padding:12px;background:var(--card)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--ok);margin-right:7px}.main{padding:26px;max-width:1500px;width:100%;margin:auto}.top{display:flex;justify-content:space-between;gap:16px;margin-bottom:18px}.title{font-size:27px;font-weight:850}.actions{display:flex;gap:8px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{background:linear-gradient(180deg,#111a29,#0c1420);border:1px solid var(--line);border-radius:15px;padding:16px}.label{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.num{font-size:28px;font-weight:850;margin:4px 0}.two{display:grid;grid-template-columns:1.1fr .9fr;gap:12px;margin-top:12px}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:12px}.list{display:grid;gap:7px}.row{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:10px;border:1px solid var(--line);border-radius:10px;background:#0b1320}.pill{font-size:11px;padding:4px 8px;border-radius:999px;background:#19263b}.ok{background:#103126;color:#9af0ce}.warn{background:#332814;color:#ffd28c}.bad{background:#351923;color:#ffb3bd}.form{display:grid;gap:9px}.field{display:grid;gap:4px}.field label{font-size:12px;color:var(--muted)}input,textarea,select{width:100%;padding:10px;border-radius:9px;border:1px solid var(--line);background:#080e17;color:var(--text)}textarea{resize:vertical}.chat{height:390px;overflow:auto;border:1px solid var(--line);border-radius:11px;padding:12px;background:#080d15}.msg{padding:9px 11px;border-radius:10px;margin:0 0 8px;white-space:pre-wrap}.user{background:#192b4c;margin-left:15%}.assistant{background:#121d2e;margin-right:10%}.login{position:fixed;inset:0;display:grid;place-items:center;background:#05070ddd;z-index:5}.login.hide{display:none}.loginbox{width:min(440px,calc(100% - 30px));padding:24px;border:1px solid var(--line);border-radius:16px;background:var(--card)}.hide{display:none!important}.toast{position:fixed;right:20px;bottom:20px;padding:12px;background:#142033;border:1px solid var(--line);border-radius:10px;display:none;z-index:20}.toast.show{display:block}.section{margin-top:12px}.section h3{margin-top:0}.empty{padding:20px;text-align:center;color:var(--muted)}.code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:12px}.source{max-height:120px;overflow:auto}.bar{height:7px;border-radius:9px;background:#19263b;overflow:hidden}.bar>i{display:block;height:100%;background:var(--accent)}@media(max-width:1050px){.app{grid-template-columns:190px 1fr}.grid{grid-template-columns:repeat(2,1fr)}.two,.three{grid-template-columns:1fr}}@media(max-width:700px){.app{display:block}.side{position:static;height:auto;border-right:0;border-bottom:1px solid var(--line)}.nav{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.main{padding:14px}.top{flex-direction:column}}
</style></head><body>
<div id="login" class="login"><div class="loginbox"><div class="brand">ORBIT</div><p class="muted">Production AI control plane · product plane</p><div class="form"><div class="field"><label>API token</label><input id="token" type="password" autocomplete="off"></div><button onclick="login()">Connect</button></div><p class="muted" style="font-size:12px;margin-bottom:0">Your token stays in this browser's local storage.</p></div></div>
<div id="app" class="app hide"><aside class="side"><div class="brand">ORBIT</div><div class="muted">AI control plane</div><div class="nav">
<button class="active" data-p="overview" onclick="page('overview')">Overview</button><button data-p="models" onclick="page('models')">Models</button><button data-p="chat" onclick="page('chat')">Chat</button><button data-p="projects" onclick="page('projects')">Projects</button><button data-p="knowledge" onclick="page('knowledge')">Knowledge</button><button data-p="agents" onclick="page('agents')">Agents</button><button data-p="tools" onclick="page('tools')">Tools / MCP</button><button data-p="media" onclick="page('media')">Voice / Vision</button><button data-p="requests" onclick="page('requests')">Requests</button></div>
<div class="state"><span class="dot"></span><b id="state">ready</b><div id="stateDetail" class="muted">Checking…</div></div><button class="alt" style="width:100%;margin-top:14px" onclick="logout()">Sign out</button></aside>
<main class="main"><div class="top"><div><div id="title" class="title">Overview</div><div class="muted">Live ORBIT production control plane</div></div><div class="actions"><button class="alt" onclick="refresh()">Refresh</button><a href="/docs" target="_blank"><button class="alt">API Docs</button></a></div></div>
<div id="overview"><div class="grid"><div class="card"><div class="label">Service</div><div id="service" class="num">—</div></div><div class="card"><div class="label">Models</div><div id="modelsCount" class="num">—</div></div><div class="card"><div class="label">Requests</div><div id="requestsCount" class="num">—</div></div><div class="card"><div class="label">Failures</div><div id="failures" class="num">—</div></div></div><div class="two"><div class="card"><h3>System</h3><div id="system" class="list"></div></div><div class="card"><h3>Readiness</h3><div id="checks" class="list"></div></div></div><div class="card section"><h3>Product plane</h3><div id="modules" class="grid"></div></div></div>
<div id="models" class="hide"><div class="two"><div class="card"><h3>Model catalog</h3><div id="modelList" class="list"></div></div><div class="card"><h3>Register model</h3><div class="form"><div class="field"><label>ID</label><input id="mid" value="orbit-demo"></div><div class="field"><label>Display name</label><input id="mname" value="ORBIT Demo Runtime"></div><div class="field"><label>Runtime</label><input id="mrun" value="orbit-demo"></div><div class="field"><label>Capabilities</label><input id="mcaps" value="text-generation,chat,streaming,demo"></div><button onclick="registerModel()">Register</button></div><p class="muted" style="font-size:12px">Remote activation is automatic when the ORBIT OpenAI-compatible environment variables are configured.</p></div></div></div>
<div id="chat" class="hide"><div class="card"><h3>Chat / inference</h3><div id="chatBox" class="chat"></div><div class="form" style="margin-top:10px"><select id="chatModel"></select><textarea id="prompt" rows="3" placeholder="Ask ORBIT something…"></textarea><div><button onclick="send(false)">Send</button> <button class="alt" onclick="send(true)">Stream</button></div></div></div></div>
<div id="projects" class="hide"><div class="two"><div class="card"><h3>Projects</h3><div id="projectList" class="list"></div></div><div class="card"><h3>New project</h3><div class="form"><input id="projectName" placeholder="Project name"><textarea id="projectDesc" rows="3" placeholder="Description"></textarea><button onclick="createProject()">Create project</button></div></div></div></div>
<div id="knowledge" class="hide"><div class="two"><div class="card"><h3>Project knowledge</h3><div class="field"><label>Project</label><select id="knowledgeProject" onchange="loadKnowledge()"></select></div><div id="knowledgeList" class="list" style="margin-top:10px"></div></div><div class="card"><h3>Ingest / retrieve</h3><div class="form"><input id="knowledgeName" placeholder="Document name"><textarea id="knowledgeContent" rows="8" placeholder="Paste Markdown, TXT or extracted document text"></textarea><button onclick="addKnowledge()">Index document</button><input id="knowledgeQuery" placeholder="Search project knowledge"><button class="alt" onclick="searchKnowledge()">Search</button><div id="knowledgeResults" class="list"></div></div></div></div></div>
<div id="agents" class="hide"><div class="two"><div class="card"><h3>Agents</h3><div id="agentList" class="list"></div></div><div class="card"><h3>Create agent</h3><div class="form"><input id="agentName" placeholder="Agent name"><input id="agentModel" placeholder="Model id"><input id="agentCaps" placeholder="capabilities, e.g. tool:echo"><button onclick="createAgent()">Create agent</button></div></div></div></div>
<div id="tools" class="hide"><div class="two"><div class="card"><h3>Tools / MCP</h3><div id="toolList" class="list"></div></div><div class="card"><h3>Register tool</h3><div class="form"><input id="toolName" placeholder="echo"><input id="toolDesc" placeholder="Description"><input id="toolCap" value="tool:echo" placeholder="Capability"><button onclick="createTool()">Register tool</button><textarea id="toolArgs" rows="4" placeholder='{"text":"hello"}'></textarea><input id="toolRunCaps" placeholder="Capabilities: tool:echo"><button class="alt" onclick="runTool()">Run selected tool</button><div id="toolResult" class="code"></div></div></div></div></div>
<div id="media" class="hide"><div class="two"><div class="card"><h3>Voice / Vision media</h3><p class="muted">Durable media storage is active. Upload image/audio now; an installed STT/TTS/vision engine can consume the same media records later.</p><div class="form"><input id="mediaFile" type="file" accept="image/*,audio/*,.txt,.md"><button onclick="uploadMedia()">Upload media</button></div></div><div class="card"><h3>Stored media</h3><div id="mediaList" class="list"></div></div></div></div>
<div id="requests" class="hide"><div class="card"><h3>Recent requests</h3><div id="requestList" class="list"></div></div></div>
</main></div><div id="toast" class="toast"></div>
<script>
const S={token:localStorage.getItem('orbit_token')||'',page:'overview',projects:[],selectedTool:''};
const $=id=>document.getElementById(id); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(x){$('toast').textContent=x;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600)}
function hdr(){return {'Content-Type':'application/json','Authorization':'Bearer '+S.token}}
async function api(path,opt={}){const r=await fetch(path,{...opt,headers:{...hdr(),...(opt.headers||{})}});const d=await r.json().catch(()=>({detail:r.statusText}));if(r.status===401){logout();throw Error('Authentication required')}if(!r.ok)throw Error(d.detail||'Request failed');return d}
async function upload(path,form){const r=await fetch(path,{method:'POST',headers:{'Authorization':'Bearer '+S.token},body:form});const d=await r.json().catch(()=>({detail:r.statusText}));if(!r.ok)throw Error(d.detail||'Upload failed');return d}
function login(){S.token=$('token').value.trim();api('/v1/session').then(()=>{localStorage.setItem('orbit_token',S.token);$('login').classList.add('hide');$('app').classList.remove('hide');refresh()}).catch(()=>{S.token='';toast('Invalid token')})}
function logout(){S.token='';localStorage.removeItem('orbit_token');$('app').classList.add('hide');$('login').classList.remove('hide')}
const pages=['overview','models','chat','projects','knowledge','agents','tools','media','requests'];
function page(p){S.page=p;pages.forEach(x=>$(x).classList.toggle('hide',x!==p));document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.p===p));$('title').textContent=p==='tools'?'Tools / MCP':p==='media'?'Voice / Vision':p[0].toUpperCase()+p.slice(1);loadPage(p)}
async function loadPage(p){try{if(p==='overview'||p==='models'||p==='chat')await loadModels();if(p==='projects')await loadProjects();if(p==='knowledge'){await loadProjects();await loadKnowledge()}if(p==='agents')await loadAgents();if(p==='tools')await loadTools();if(p==='media')await loadMedia();if(p==='requests')await loadRequests()}catch(e){toast(e.message)}}
async function refresh(){try{const [root,h,m,r,sys,plat]=await Promise.all([fetch('/').then(x=>x.json()),fetch('/health').then(x=>x.json()),api('/v1/metrics'),api('/v1/requests?limit=100'),api('/v1/system'),api('/v1/platform')]);$('service').textContent=String(root.status||'ok').toUpperCase();$('modelsCount').textContent=(await api('/v1/models')).data.length;$('requestsCount').textContent=r.data.length;$('failures').textContent=m.failed_requests||0;$('state').textContent=h.state;$('stateDetail').textContent=h.status==='ok'?'All systems healthy':'Attention required';$('checks').innerHTML=h.checks.map(x=>`<div class="row"><span>${esc(x.name)}</span><span class="pill ${x.status==='healthy'?'ok':''}">${esc(x.status)}</span></div>`).join('');$('system').innerHTML=`<div class="row"><span>Platform</span><b>${esc(sys.platform)}</b></div><div class="row"><span>Architecture</span><b>${esc(sys.architecture)}</b></div><div class="row"><span>Memory</span><b>${sys.memory_bytes?Math.round(sys.memory_bytes/1073741824*10)/10+' GiB':'—'}</b></div>`;$('modules').innerHTML=Object.entries(plat.modules||{}).map(([k,v])=>`<div class="card"><div class="label">${esc(k)}</div><div class="pill ${v?'ok':'bad'}">${v?'ACTIVE':'OFF'}</div></div>`).join('');renderRequests(r.data)}catch(e){toast(e.message)}}
function renderRequests(d){$('requestList').innerHTML=d.length?d.map(x=>`<div class="row"><span><b class="code">${esc(x.request_id)}</b><br><span class="muted">${esc(x.model||'unknown')} · ${esc(x.runtime||'unknown')}</span></span><span class="pill ${x.state==='completed'?'ok':x.state==='failed'?'bad':''}">${esc(x.state)}</span></div>`).join(''):'<div class="empty">No requests yet.</div>'}
async function loadRequests(){renderRequests((await api('/v1/requests?limit=100')).data)}
async function loadModels(){const d=await api('/v1/models');$('modelList').innerHTML=d.data.length?d.data.map(x=>`<div class="row"><span><b>${esc(x.id)}</b><br><span class="muted">${esc(x.display_name||x.state)} · ${esc((x.runtimes||[]).join(', '))}</span></span><span class="pill ${x.state==='ready'?'ok':x.state==='error'?'bad':''}">${esc(x.state)}</span></div>`).join(''):'<div class="empty">No models registered.</div>';$('chatModel').innerHTML=d.data.map(x=>`<option value="${esc(x.id)}">${esc(x.display_name||x.id)}</option>`).join('')}
async function registerModel(){try{await api('/v1/models',{method:'POST',body:JSON.stringify({id:$('mid').value.trim(),display_name:$('mname').value.trim(),modality:'text',capabilities:$('mcaps').value.split(',').map(x=>x.trim()).filter(Boolean),runtimes:[$('mrun').value.trim()],tags:['ui']})});toast('Model registered');loadModels();refresh()}catch(e){toast(e.message)}}
async function send(stream){const p=$('prompt').value.trim(),model=$('chatModel').value;if(!p||!model)return toast('Select a model and enter a message');$('chatBox').innerHTML+=`<div class="msg user">${esc(p)}</div>`;$('prompt').value='';try{if(!stream){const d=await api('/v1/chat/completions',{method:'POST',body:JSON.stringify({model,messages:[{role:'user',content:p}],stream:false})});$('chatBox').innerHTML+=`<div class="msg assistant">${esc(d.choices[0].message.content)}</div>`}else{const r=await fetch('/v1/chat/completions',{method:'POST',headers:hdr(),body:JSON.stringify({model,messages:[{role:'user',content:p}],stream:true})});if(!r.ok)throw Error((await r.text())||'stream failed');const reader=r.body.getReader(),dec=new TextDecoder();let out='';$('chatBox').innerHTML+=`<div id="streamMsg" class="msg assistant"></div>`;while(true){const {value,done}=await reader.read();if(done)break;const text=dec.decode(value,{stream:true});for(const line of text.split('\n')){if(!line.startsWith('data: ')||line==='data: [DONE]')continue;try{const d=JSON.parse(line.slice(6));out+=d.choices?.[0]?.delta?.content||'';$('streamMsg').textContent=out}catch{}}}$('streamMsg').removeAttribute('id')}$('chatBox').scrollTop=$('chatBox').scrollHeight;refresh()}catch(e){$('chatBox').innerHTML+=`<div class="msg assistant">Error: ${esc(e.message)}</div>`}}
async function loadProjects(){const d=await api('/v1/projects');S.projects=d.data;$('projectList').innerHTML=d.data.length?d.data.map(x=>`<div class="row"><span><b>${esc(x.name)}</b><br><span class="muted">${esc(x.description||'')}</span></span><span class="pill">${esc(x.id)}</span></div>`).join(''):'<div class="empty">No projects yet.</div>';$('knowledgeProject').innerHTML=d.data.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}
async function createProject(){try{await api('/v1/projects',{method:'POST',body:JSON.stringify({name:$('projectName').value.trim(),description:$('projectDesc').value.trim()})});$('projectName').value='';$('projectDesc').value='';toast('Project created');loadProjects()}catch(e){toast(e.message)}}
async function loadKnowledge(){const id=$('knowledgeProject').value;if(!id){$('knowledgeList').innerHTML='<div class="empty">Create a project first.</div>';return}const d=await api('/v1/projects/'+encodeURIComponent(id));$('knowledgeList').innerHTML=d.documents?.length?d.documents.map(x=>`<div class="row"><span><b>${esc(x.name)}</b><br><span class="code">${esc(x.sha256)}</span></span><span class="pill ok">indexed</span></div>`).join(''):'<div class="empty">No indexed documents.</div>'}
async function addKnowledge(){try{const id=$('knowledgeProject').value;if(!id)throw Error('Select a project');await api('/v1/projects/'+encodeURIComponent(id)+'/knowledge',{method:'POST',body:JSON.stringify({name:$('knowledgeName').value.trim(),content:$('knowledgeContent').value})});$('knowledgeName').value='';$('knowledgeContent').value='';toast('Document indexed');loadKnowledge()}catch(e){toast(e.message)}}
async function searchKnowledge(){try{const id=$('knowledgeProject').value,q=$('knowledgeQuery').value.trim();const d=await api('/v1/projects/'+encodeURIComponent(id)+'/knowledge/search?q='+encodeURIComponent(q),{method:'POST'});$('knowledgeResults').innerHTML=d.data.length?d.data.map(x=>`<div class="row"><span><b>${esc(x.name)}</b><br><span class="source">${esc(x.snippet)}</span></span><span class="pill">${x.score}</span></div>`).join(''):'<div class="empty">No matching sources.</div>'}catch(e){toast(e.message)}}
async function loadAgents(){const d=await api('/v1/agents');$('agentList').innerHTML=d.data.length?d.data.map(x=>`<div class="row"><span><b>${esc(x.name)}</b><br><span class="muted">${esc(x.model)} · ${(x.capabilities||[]).map(esc).join(', ')}</span></span><span class="pill">${esc(x.id)}</span></div>`).join(''):'<div class="empty">No agents yet.</div>'}
async function createAgent(){try{await api('/v1/agents',{method:'POST',body:JSON.stringify({name:$('agentName').value.trim(),model:$('agentModel').value.trim(),capabilities:$('agentCaps').value.split(',').map(x=>x.trim()).filter(Boolean)})});toast('Agent created');loadAgents()}catch(e){toast(e.message)}}
async function loadTools(){const d=await api('/v1/tools');$('toolList').innerHTML=d.data.length?d.data.map(x=>`<div class="row" onclick="S.selectedTool='${esc(x.name)}';$('toolName').value='${esc(x.name)}'" style="cursor:pointer"><span><b>${esc(x.name)}</b><br><span class="muted">${esc(x.description)}</span></span><span class="pill">${esc(x.capability)}</span></div>`).join(''):'<div class="empty">No tools registered.</div>'}
async function createTool(){try{await api('/v1/tools',{method:'POST',body:JSON.stringify({name:$('toolName').value.trim(),description:$('toolDesc').value.trim(),capability:$('toolCap').value.trim()})});toast('Tool registered');loadTools()}catch(e){toast(e.message)}}
async function runTool(){try{const name=S.selectedTool||$('toolName').value.trim();const caps=$('toolRunCaps').value.split(',').map(x=>x.trim()).filter(Boolean);const args=JSON.parse($('toolArgs').value||'{}');const d=await api('/v1/tools/'+encodeURIComponent(name)+'/run',{method:'POST',body:JSON.stringify({arguments:args,capabilities:caps})});$('toolResult').textContent=JSON.stringify(d,null,2)}catch(e){$('toolResult').textContent=e.message}}
async function loadMedia(){const d=await api('/v1/media');$('mediaList').innerHTML=d.data.length?d.data.map(x=>`<div class="row"><span><b>${esc(x.name)}</b><br><span class="muted">${esc(x.kind)} · ${esc(x.mime_type)} · ${x.size_bytes} bytes</span></span><span class="pill ok">stored</span></div>`).join(''):'<div class="empty">No media stored.</div>'}
async function uploadMedia(){try{const f=$('mediaFile').files[0];if(!f)return toast('Choose a file');const form=new FormData();form.append('file',f);const d=await upload('/v1/media',form);toast('Media stored: '+d.kind);$('mediaFile').value='';loadMedia()}catch(e){toast(e.message)}}
if(S.token){api('/v1/session').then(()=>{$('login').classList.add('hide');$('app').classList.remove('hide');refresh()}).catch(()=>logout())}
</script></body></html>'''
